-- Seeds the geography and category catalog (0112) with what the code and data files held until now, so the
-- database starts out equal to them: Thane live, the six "Soon" districts, every district India Post's directory has
-- as off, Thane's 205 areas with the PIN codes their businesses' addresses show, and the 327 categories (51 of them
-- with 156 sub-categories). Generated 2026-10-09 from packages/shared/src/lib/directory/places.json and the website's
-- content/local/thane-places.json, thane-taxonomy.json, thane-listings.json and subcategories.json. Every seeded slug
-- is locked: it is already in public addresses.

ON CONFLICT (state_code, slug) DO NOTHING;
--> statement-breakpoint

-- Every other district India Post's directory knows (the PIN import runs on production before this): off until staff open it.
SELECT DISTINCT ON (state_code, district_slug) state_code, district_slug, district_name, 'off', now(), gen_random_uuid()
FROM india_pincodes
ORDER BY state_code, district_slug, district_name
ON CONFLICT (state_code, slug) DO NOTHING;
--> statement-breakpoint

ON CONFLICT (district_id, slug) DO NOTHING;
--> statement-breakpoint

ON CONFLICT (slug) DO NOTHING;
